package com.aliothmoon.maafw.once;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;
/** v33/v34 scalar geometry plus manual known literals and raster; not a replay of native OCR. */
public class SelectedPendingBusinessTest {
 static final int W=1440,H=2560;
 static byte[] beforePixels(){return IndependentCurrentCardTest.pixels(true);}static List<FrameStructureEvidence.Line> beforeRows(){return IndependentCurrentCardTest.rows();}
 static byte[] afterPixels(){byte[] p=beforePixels();IndependentCurrentCardTest.fill(p,114,661,1326,1069,247);IndependentCurrentCardTest.fill(p,114,661,1326,837,255);IndependentCurrentCardTest.tick(p,1206,717);return p;}
 static List<FrameStructureEvidence.Line> afterRows(){var r=beforeRows();r.removeIf(q->q.y()>=661&&q.y()<1069);r.add(IndependentCurrentCardTest.r("Do you know the answer?",.99,153,709,825,781));r.add(IndependentCurrentCardTest.r("5",.99,1146,712,1201,778));return r;}
 static LiveRewardCardObservation.Frame frame(byte[] p,List<FrameStructureEvidence.Line> rows){return LiveRewardCardObservation.observe("selected-fixture",1,p,W,H,rows,()->false,LiveRewardCardObservation.TargetSpec.moreTriviaSelectedPendingB());}
 @Test public void nativeBusinessProofSelectsOnlyExactBWhileAnonymousCompleteAndUnknownCvStaySeparate(){var f=frame(beforePixels(),beforeRows());assertEquals(LiveRewardCardObservation.Status.OBSERVED,f.status());assertTrue(f.selectedProofReady());assertTrue(f.selectedBeforeB());assertFalse(f.selectedAllComplete());assertEquals(2,f.cards().size());int targets=0;for(var c:f.cards())if(c.configuredTarget(LiveRewardCardObservation.TargetSpec.moreTriviaSelectedPendingB())){targets++;assertFalse(c.complete());}assertEquals(1,targets);assertTrue(f.selectedEvidenceSummary().contains("unmodeledCv="));}
 @Test public void eachKnownOwnTickSupportsOnlyVisibleSetFactAfterBodyDisappears(){var f=frame(afterPixels(),afterRows());assertTrue(f.selectedProofReady());assertTrue(f.selectedAllComplete());assertFalse(f.selectedBeforeB());for(var c:f.cards())assertFalse(c.configuredTarget(LiveRewardCardObservation.TargetSpec.moreTriviaSelectedPendingB()));}
 @Test public void fullSplitFragmentOrLowExtraKnownTitleAnywhereBlocksBusiness(){for(int v=0;v<4;v++){var r=beforeRows();if(v==0)r.add(IndependentCurrentCardTest.r("Do you know the answer?",.1,400,2180,1000,2220));if(v==1){r.add(IndependentCurrentCardTest.r("Do you know the",.99,400,2180,800,2220));r.add(IndependentCurrentCardTest.r("answer?",.1,400,2230,600,2270));}if(v==2)r.add(IndependentCurrentCardTest.r("Do you know the",.1,400,2180,800,2220));if(v==3)r.add(IndependentCurrentCardTest.r("answer?",.1,150,990,280,1020));assertEquals(LiveRewardCardObservation.Status.HOLD,frame(beforePixels(),r).status());}}
 @Test public void fullOldPendingRiskAndNoncontiguousULeftIdentityGuardsRemain(){for(String token:List.of("earned","credited","complete","已获得")){var r=beforeRows();r.add(IndependentCurrentCardTest.r(token,.1,150,990,280,1020));assertEquals(token,LiveRewardCardObservation.Status.HOLD,frame(beforePixels(),r).status());}
  var r=beforeRows();r.removeIf(q->q.text().equals("SYNTHETIC_UNKNOWN_NOT_RECOVERED"));r.add(IndependentCurrentCardTest.r("Challenge yourself with",.1,150,740,280,760));r.add(IndependentCurrentCardTest.r("unknown",.1,150,770,280,790));r.add(IndependentCurrentCardTest.r("these trivia questions",.1,150,800,280,820));assertEquals(LiveRewardCardObservation.Status.HOLD,frame(beforePixels(),r).status());}
 @Test public void missingLowWrongBodyOrBothPendingCannotAuthorizeB(){for(int v=0;v<4;v++){var r=beforeRows();if(v==0)r.removeIf(q->q.text().equals("these topics"));if(v==1)IndependentCurrentCardTest.replace(r,877,"Test your knowledge on",.1);if(v==2){IndependentCurrentCardTest.replace(r,877,"Challenge yourself with",.99);IndependentCurrentCardTest.replace(r,949,"these trivia questions",.99);}if(v==3)IndependentCurrentCardTest.replace(r,826,"+10",.99);var f=frame(beforePixels(),r);assertFalse("case="+v,f.selectedBeforeB());}}
 @Test public void afterMissingLowWrongNumberOrAbsentSecondCardCannotReportSetCompletion(){for(int v=0;v<4;v++){var r=afterRows();byte[] p=afterPixels();if(v==0){IndependentCurrentCardTest.fill(p,1206,717,1270,781,255);}if(v==1)IndependentCurrentCardTest.replace(r,712,"5",.1);if(v==2)IndependentCurrentCardTest.replace(r,1744,"10",.99);if(v==3){IndependentCurrentCardTest.fill(p,114,1693,1326,1869,247);r.removeIf(q->q.y()>=1693&&q.y()<1869);}assertFalse("case="+v,frame(p,r).selectedAllComplete());}}
 static final class Rig {
  long now=1000;int taps,burns;final NativeRewardCardSession session;
  Rig(){var authority=new NativeRewardCardSession.Authority(){public long elapsedRealtime(){return now;}public boolean scopeCurrent(){return true;}public boolean sourceStillMatches(int w,int h,int r){return w==W&&h==H&&r==0;}public void consumeOneTap(ReviewShizukuTapActor.TapTarget t){burns++;}};
   var actor=new ReviewShizukuTapActor(()->new ReviewShizukuTapActor.Session(){public ReviewShizukuTapActor.DisplayShape display(){return new ReviewShizukuTapActor.DisplayShape(W,H,0);}public boolean stillReady(){return true;}public ReviewShizukuTapActor.PendingTap dispatch(ReviewShizukuTapActor.TapTarget t,ReviewShizukuTapActor.FinalGate gate)throws Exception{gate.requireValid();taps++;return new ReviewShizukuTapActor.PendingTap(){public boolean waitForExit(long ms){return true;}public int exitCode(){return 0;}public void destroy(){}public void close(){}};}});
   var back=new ReviewShizukuBackActor(()->{throw new AssertionError("Already Template: no Back");});
   var ret=new NativeBingReturnController("selected-session",new NativeBingReturnController.Ports(){public long elapsedRealtime(){return now;}public boolean authorityCurrent(BingNavigationSnapshot.Shape s){return true;}public BingNavigationSnapshot.Ready originalSource(){return ready();}public BingNavigationSnapshot.Result observe(BingNavigationSnapshot.Shape s){return source();}public void consumeReturn(ReviewShizukuBackActor.BackTarget t){throw new AssertionError("No Back");}public void pollPause(){}},back,true);
   session=new NativeRewardCardSession("selected-session",60000,authority,actor,LiveRewardCardObservation.TargetSpec.moreTriviaSelectedPendingB(),ret);
  }
  BingNavigationSnapshot.Result source(){String c=BingNavigationSnapshot.TEMPLATE;return BingNavigationSnapshot.parse(BingNavigationFixture.windows(c,"aaa","ddd","15").replace("w=523 h=1000","w=1440 h=2560"),BingNavigationFixture.activities(c,"ddd","15",true),new BingNavigationSnapshot.Profile(10073,10049,new BingNavigationSnapshot.Shape(W,H,0)),now,now);}
  BingNavigationSnapshot.Ready ready(){return source().ready();}
  NativeRewardCardSession.Capture capture(NativeRewardCardSession.Phase p){return session.startCapture(p,W,H,0);}
 }
 @Test public void sessionOneBInputThenNewSameSourceSetCompletionUsesNoSameTaskAttribution(){var r=new Rig();var c=r.capture(NativeRewardCardSession.Phase.BEFORE);var o=c.prepare(beforePixels(),W,H,beforeRows(),()->false);var first=r.session.acceptAfterCleanup(c,o,true,()->true,o.configuredTarget());assertEquals(NativeRewardCardSession.Outcome.AWAITING_NEW_OBSERVATION,first.outcome());assertEquals(1,r.taps);assertEquals(1,r.burns);r.now+=1000;c=r.capture(NativeRewardCardSession.Phase.AFTER);o=c.prepare(afterPixels(),W,H,afterRows(),()->false);var after=r.session.acceptAfterCleanup(c,o,true,()->true,null);assertEquals(NativeRewardCardSession.Outcome.OBSERVED_VISIBLE_KNOWN_SET_COMPLETE,after.outcome());assertFalse(after.causedByTap());assertFalse(after.accountCreditKnown());assertEquals(1,r.taps);}
 @Test public void passingAnonymousMemberAsSelectionCannotClaimTargetAlreadyComplete(){var r=new Rig();var c=r.capture(NativeRewardCardSession.Phase.BEFORE);var o=c.prepare(beforePixels(),W,H,beforeRows(),()->false);var anon=o.cards().stream().filter(LiveRewardCardObservation.Card::complete).findFirst().orElseThrow();var receipt=r.session.acceptAfterCleanup(c,o,true,()->true,anon);assertEquals(NativeRewardCardSession.Outcome.HOLD,receipt.outcome());assertEquals(0,r.taps);}
 @Test public void readonlyObjectsAndOldSpecCannotProduceSelectedProof(){var readonly=ReadOnlyTwoStageRun.Capture.moreCurrentCards(new Object(),"readonly-not-proof",W,H,0,1000,()->false).prepare(beforePixels(),W,H,beforeRows(),()->false);assertNotNull(readonly.currentCards());assertFalse(readonly.frame.selectedProofReady());assertFalse(LiveRewardCardObservation.observe("old-spec",1,beforePixels(),W,H,beforeRows(),()->false,LiveRewardCardObservation.TargetSpec.moreTriviaChallengeBounded()).selectedProofReady());}
 @Test public void completeHeaderAloneOrDuplicateHeaderFieldNeverBecomesRosterProof(){
  var r=beforeRows();IndependentCurrentCardTest.replace(r,450,"25/25",.99);assertFalse(frame(beforePixels(),r).selectedProofReady());
  r=afterRows();IndependentCurrentCardTest.replace(r,450,"25/25",.99);r.removeIf(q->q.y()==1744);assertFalse(frame(afterPixels(),r).selectedAllComplete());
  r=beforeRows();r.add(IndependentCurrentCardTest.r("?",.1,55,440,381,536));assertEquals(LiveRewardCardObservation.Status.HOLD,frame(beforePixels(),r).status());
 }
}
